'use strict';
const data=JSON.parse(document.getElementById('site-data').textContent);
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const saved={get(k,d=null){try{return JSON.parse(localStorage.getItem('creeds-v1-'+k))??d}catch{return d}},set(k,v){try{localStorage.setItem('creeds-v1-'+k,JSON.stringify(v));return true}catch{return false}}};
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,3500)}
