function setToc(open){if(matchMedia('(max-width:960px)').matches){document.body.classList.toggle('toc-mobile-open',open);if(open)$('#toc-close').focus()}else document.body.classList.toggle('toc-hidden',!open);$('#toc-toggle').setAttribute('aria-expanded',open)}
$('#toc-toggle').addEventListener('click',()=>setToc(matchMedia('(max-width:960px)').matches?!document.body.classList.contains('toc-mobile-open'):document.body.classList.contains('toc-hidden')));
function closeMobile(){document.body.classList.remove('toc-mobile-open');if(matchMedia('(max-width:960px)').matches)$('#toc-toggle').setAttribute('aria-expanded','false')}
$('#toc-close').onclick=()=>{closeMobile();$('#toc-toggle').focus()};$('#backdrop').onclick=closeMobile;
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobile()});
if(matchMedia('(max-width:960px)').matches)$('#toc-toggle').setAttribute('aria-expanded','false');
$('#focus-toggle').onclick=()=>{document.body.classList.toggle('focus-mode');setToc(false);toast('已切换专注阅读；可用顶部目录按钮恢复目录')};
$$('.toc a').forEach(a=>a.addEventListener('click',closeMobile));
$('#to-top').onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});
let currentId='top', scrollTimer;
const anchors=$$('section.chapter[id],.clause[id]');
const observer=new IntersectionObserver(entries=>{for(const en of entries)if(en.isIntersecting){currentId=en.target.id;$$('#toc a.current').forEach(a=>a.classList.remove('current'));const link=$(`#toc a[href="#${currentId}"]`);if(link)link.classList.add('current');saved.set('position',currentId)}},{rootMargin:'-85px 0px -65% 0px',threshold:0});anchors.forEach(a=>observer.observe(a));
function updateProgress(){const h=document.documentElement.scrollHeight-innerHeight;const n=h>0?Math.min(100,Math.round(scrollY/h*100)):100;$('#progress').style.width=n+'%';$('#read-progress').textContent='阅读进度 '+n+'%'}
addEventListener('scroll',()=>{cancelAnimationFrame(scrollTimer);scrollTimer=requestAnimationFrame(updateProgress)},{passive:true});updateProgress();
const last=saved.get('position');if(last&&document.getElementById(last)){const resume=$('#resume');resume.hidden=false;resume.href='#'+last;resume.textContent='继续上次阅读 →';}
$('#search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();const out=$('#search-results');out.replaceChildren();if(!q){$('#toc-links').hidden=false;return}$('#toc-links').hidden=true;let found=anchors.filter(a=>a.textContent.toLowerCase().includes(q));found=found.filter(a=>!found.some(b=>b!==a&&a.contains(b)));found.slice(0,35).forEach(a=>{const link=document.createElement('a');link.href='#'+a.id;link.textContent=(a.querySelector('h2,h3')?.textContent||a.id);link.onclick=closeMobile;out.append(link)});if(!found.length)out.textContent='没有找到，请试试“三一”“复活”或“圣约”。';else{const count=document.createElement('p');count.className='small';count.textContent=`找到 ${found.length} 个段落${found.length>35?'，显示前35项':''}`;out.prepend(count)}});
// Local map: geography is approximate; no third-party map service is loaded.
function selectPlace(i){const p=data.places[i];$$('[data-place]').forEach(b=>{const active=Number(b.dataset.place)===i;b.classList.toggle('active',active);if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',active)});const box=$('#place-info');box.replaceChildren();const title=document.createElement('h3');title.textContent=`${String(i+1).padStart(2,'0')} · ${p.name}`;const body=document.createElement('p');body.textContent=p.body;const culture=document.createElement('p');const strong=document.createElement('strong');strong.textContent='文化与处境：';culture.append(strong,document.createTextNode(p.culture));const coords=document.createElement('div');coords.className='small';coords.textContent=`约略坐标 ${p.lat}°N, ${p.lon}°E · ${p.uncertainty||'现代定位，不代表古代边界'}`;box.append(title,body,culture,coords)}
data.places.forEach((p,i)=>{const b=document.createElement('button');b.dataset.place=i;b.textContent=`${i+1} ${p.name.split('／')[0].split('/')[0]}`;b.onclick=()=>selectPlace(i);$('#map-buttons').append(b)});
$$('.map [data-place]').forEach(m=>{m.addEventListener('click',()=>selectPlace(Number(m.dataset.place)));m.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectPlace(Number(m.dataset.place))}})});selectPlace(0);
const scenes=[['创造与托付','神的形象不是自我神化，而是受造者在神面前承担治理、敬拜与爱邻舍的使命。','创1–2'],['背约与应许','罪使人进入死亡，但神主动应许女人的后裔。救恩故事从神的怜悯开始，而不是人的自救计划。','创3'],['以色列与预表','应许经亚伯拉罕、出埃及、西奈与大卫之约推进。祭物、圣所与王权，把盼望引向仍未来到的成全。','创12；出19；撒下7'],['基督与成就','永恒的子成为真人，顺服、受死并复活；不是神性转变为人性，而是子真实取了人性。','约1；腓2；林前15'],['圣灵与教会','圣灵藉福音使人信靠基督，把来自万国的人聚集为教会。圣道与圣礼服事同一个福音。','徒2；弗2；林前12'],['复活与同住','最后审判使邪恶不能永远得胜。基督拯救的是完整的人，终点是身体复活与神同住的新创造。','林前15；启21–22']];
let scene=0,playing=false,storyTimer;
function showScene(){const el=$('#story-display');el.replaceChildren();const n=document.createElement('div');n.className='big-num';n.textContent=String(scene+1).padStart(2,'0');const content=document.createElement('div');const title=document.createElement('h3');title.textContent=scenes[scene][0];const p=document.createElement('p');p.textContent=scenes[scene][1];const ref=document.createElement('small');ref.style.color='#d3e1b9';ref.textContent=scenes[scene][2];content.append(title,p,ref);el.append(n,content);}
function stopStory(){playing=false;clearInterval(storyTimer);$('#story-play').textContent='▶ 播放故事线';$('#story-play').setAttribute('aria-pressed','false')}
$('#story-play').onclick=()=>{if(playing)return stopStory();playing=true;$('#story-play').textContent='Ⅱ 暂停故事线';$('#story-play').setAttribute('aria-pressed','true');storyTimer=setInterval(()=>{scene=(scene+1)%scenes.length;showScene()},7000)};
$('#story-prev').onclick=()=>{stopStory();scene=(scene+5)%6;showScene()};$('#story-next').onclick=()=>{stopStory();scene=(scene+1)%6;showScene()};showScene();
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopStory()});
const reading={apostles:{name:'使徒信经',path:'apostles-creed',outline:'【原创记忆提纲，不是信经原文】\n\n一 · 父与创造\n独一的神，全能的父；天地出于他的创造与护理。\n\n二 · 子与救赎\n耶稣基督是主，是独生子。\n由圣灵成孕，从马利亚取了真实的人性。\n在彼拉多执政时受难、钉十字架、受死、埋葬。\n降卑到底；第三日身体复活。\n升天、掌权；将再来审判活人与死人。\n\n三 · 灵与新生命\n圣灵是真神，使人得着基督。\n一间圣而公的教会，圣徒彼此相通。\n罪蒙赦免，身体复活，享有永生。\n\n记忆路线：父 → 子降卑 → 子升高 → 灵 → 教会 → 终末。'},nicene:{name:'尼西亚信经',path:'nicene-creed',outline:'【原创记忆提纲，不是信经原文】\n\n一 · 独一的父\n创造可见与不可见的一切。\n\n二 · 独一的主耶稣基督\n子在永恒中受生，与父同具神性。\n受生不是受造；万有藉他而成。\n他为人类的救赎降临，成为真人。\n受难、埋葬、复活、升天，再临审判；国度没有终结。\n\n三 · 圣灵与教会的盼望\n圣灵是主与生命的赐予者，与父子同受敬拜。\n原始381文本说从父而出；指定西方版本含“和子”条款。\n圣灵藉先知发言。\n一间圣洁、大公、使徒性的教会。\n一次洗礼；罪得赦免；死人复活；来世生命。\n\n记忆路线：创造 → 同质 → 取肉身 → 十架与复活 → 圣灵 → 教会与终末。'},athanasian:{name:'亚他那修信经',path:'athanasian-creed',outline:'【原创记忆提纲，不是信经原文】\n\n开头 · 信仰关系到救恩\n不是术语考试，而是不可把所信的神和救主换成另一位。\n\n第一部分 · 一体三位\n位格不混淆，本质不分割。\n父、子、灵同为非受造、无限、永恒、全能的神。\n不是三位神，也不是一位神的三个面具。\n父不受生；子由父受生；灵由父与子而出。\n三个位格同尊同荣，没有神性等级。\n\n第二部分 · 一位二性\n基督完全是神，也完全是人，有真实的人身与理性灵魂。\n神性与人性不混合；联合不产生两位基督。\n只有一位子，真实经历受难、复活、升天与再临。\n\n结尾 · 审判与永生\n所有人复活，所行的显明。\n善行是活信心的果子，不是换取称义的功劳。\n\n记忆路线：救恩关切 → 三一 → 道成肉身 → 审判 → 信仰关切。'}};
let readerKey='apostles',masked=false,speaking=false,readerMode='original';
function readerText(){if(readerMode==='outline')return reading[readerKey].outline;return saved.get('text-'+readerKey,'')||data.originals?.[readerKey]||reading[readerKey].outline}
function stopSpeech(){if('speechSynthesis'in window)speechSynthesis.cancel();speaking=false;$('#speak-toggle').textContent='▷ 朗读'}
function renderReader(){const item=reading[readerKey],imported=saved.get('text-'+readerKey,'');$('#reader-title').textContent=item.name+(readerMode==='outline'?' · 记忆路线':imported?' · 本机导入阅读版':' · 原文阅读版');$('#reader-label').textContent=readerMode==='outline'?'原创记忆提纲 · 不是信经原文':imported?'用户本机导入 · 未自动校验版本':'指定网站中文原文 · 完整文本';$('#reader-mode').textContent=readerMode==='outline'?'切换到正式原文':'切换到记忆提纲';$('#reader-source').href='https://ccifellowship.org/books/book-of-praise/creeds/'+item.path;$$('[data-reader]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.reader===readerKey));const text=readerText();const el=$('#reader-text');el.replaceChildren();if(!masked)el.textContent=text;else{let count=0;const tokens=text.match(/[\u3400-\u9fff]{1,3}|[^\u3400-\u9fff]+/g)||[text];for(const token of tokens){if(/^[\u3400-\u9fff]/.test(token)&&++count%3===0){const span=document.createElement('span');span.className='hidden-word';span.textContent=token;span.tabIndex=0;span.setAttribute('role','button');span.setAttribute('aria-label','揭示遮住的词');const reveal=()=>{span.className='revealed';span.removeAttribute('tabindex');span.removeAttribute('role');span.removeAttribute('aria-label')};span.onclick=reveal;span.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();reveal()}};el.append(span)}else el.append(document.createTextNode(token));}}$('#mask-toggle').setAttribute('aria-pressed',masked);$('#import-text').value=imported;$('#reader-status').textContent=readerMode==='outline'?'当前为原创提纲，用来帮助理解与记忆。':imported?'已使用个人本机文本；请自行核对版本。':'正文来自 ccifellowship.org；已保留网站字词、标点与段号。';}
$$('[data-reader]').forEach(b=>b.onclick=()=>{stopSpeech();readerKey=b.dataset.reader;masked=false;renderReader()});
$('#reader-mode').onclick=()=>{stopSpeech();readerMode=readerMode==='original'?'outline':'original';masked=false;renderReader()};
$('#mask-toggle').onclick=()=>{masked=!masked;renderReader()};
$('#save-import').onclick=()=>{const text=$('#import-text').value;if(!text.trim())return toast('请先粘贴或选择有权使用的文本');if(text.length>100000)return toast('文本过长，请仅导入当前一份信经');const ok=saved.set('text-'+readerKey,text);if(!ok)return toast('浏览器无法保存本机文本，请检查隐私或存储设置');masked=false;renderReader();toast('已在本机保存，未上传')};
$('#clear-import').onclick=()=>{saved.set('text-'+readerKey,'');masked=false;renderReader();toast('本篇导入文本已清除')};
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>400000)return toast('请使用小于400KB的纯文本文件');$('#import-text').value=await file.text();toast('文件已载入，请核对后保存')});
$('#speak-toggle').onclick=()=>{if(!('speechSynthesis'in window))return toast('当前浏览器不支持朗读');if(speaking)return stopSpeech();stopSpeech();const paragraphs=readerText().split(/\n+/).filter(Boolean);let index=0;speaking=true;$('#speak-toggle').textContent='Ⅱ 停止朗读';function next(){if(!speaking||index>=paragraphs.length){stopSpeech();return}const u=new SpeechSynthesisUtterance(paragraphs[index++]);u.lang='zh-CN';u.rate=.88;const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('zh'));if(voice)u.voice=voice;u.onend=next;u.onerror=e=>{stopSpeech();if(e.error!=='canceled'&&e.error!=='interrupted')toast('设备语音暂不可用，请检查系统中文语音包')};speechSynthesis.speak(u)}next()};
$('#speech-stop').onclick=stopSpeech;
$('#reader-print').onclick=()=>{document.body.classList.add('reader-only');window.print()};addEventListener('afterprint',()=>document.body.classList.remove('reader-only'));
$('#print-all').onclick=()=>{document.body.classList.remove('reader-only');window.print()};
function esc(t){return t.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
$('#reader-download').onclick=()=>{const imported=saved.get('text-'+readerKey,'');const html=`<!doctype html><html lang="zh-Hans"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${reading[readerKey].name} · 阅读版</title><style>body{max-width:850px;margin:50px auto;padding:0 24px;color:#173d36;background:#faf9f3;font:20px/2.3 'Songti SC',SimSun,serif}h1{text-align:center;font-size:32px}p{white-space:pre-wrap}small{font:14px/1.8 system-ui}a{color:inherit}@media print{body{margin:0;font-size:14pt}}</style><h1>${reading[readerKey].name}</h1><small>${readerMode==='outline'?'原创记忆提纲；不是信经原文':imported?'用户本机导入文本；未经自动版本校验':'指定网站中文原文 · ccifellowship.org'}</small><p>${esc(readerText())}</p><small><a href="${$('#reader-source').href}">指定原站全文</a> · 同一信仰 · 三大信经深读</small></html>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=readerKey+(readerMode==='outline'?'-study-outline':imported?'-imported-reader':'-original-reader')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};
renderReader();
const plan=['总览圣经六步；复述三经分工','使徒信经：父、子、灵三段','尼西亚：受生非受造；同质','复习前两篇；在地图找会议','亚他那修：一体三位、一位二性','读海44、比19/24/37；辨难点','闭卷讲完整主线；做六题自测'];
plan.forEach((t,i)=>{const box=document.createElement('div');box.className='day';const b=document.createElement('b');b.textContent='DAY '+(i+1);const label=document.createElement('label');const input=document.createElement('input');input.type='checkbox';input.checked=saved.get('day-'+i,false);input.onchange=()=>saved.set('day-'+i,input.checked);label.append(input,document.createTextNode(' '+t));box.append(b,label);$('#plan-days').append(box)});
const quizzes=[{q:'“父、子、灵”是否代表神的三个工作部门？',a:['是，各自独立负责一部分','否，位格有区别，对外工作不可分割'],correct:1,why:'教学上的归属不等于排他分工；只有子道成肉身，但救恩是三一神的共同工作。'},{q:'通行《尼西亚信经》应怎样描述？',a:['325文本、381文本与西方增补必须分层说明','325年完成了今天所有版本的每个词'],correct:0,why:'381通行形式与325版本不同；“和子”属于西方后续历史，不能倒写进381原文。'},{q:'《亚他那修信经》的作者是谁？',a:['一定是亚他那修本人','作者不详，形成于后来的西方拉丁环境'],correct:1,why:'名称表达历史上的归属传统，不是可靠的亲笔署名。'},{q:'“基督一位二性”意味着什么？',a:['一个位格，完全神性与完全人性','两个位格合作成为一个救主'],correct:0,why:'二性不混合，也不把基督分成两位。子取了人性，仍是同一位子。'},{q:'末日按行为审判，是否推翻因信称义？',a:['是，人的功劳最后补足基督','否，善行显明信心的果子，救恩根基仍是基督'],correct:1,why:'改革宗区分称义的根基、领受的工具与信心的果子；不可取消审判，也不可把果子变为功劳。'},{q:'海德堡问答44对降阴间的解释处于什么层次？',a:['证明古代所有教会都只这样理解','16世纪改革宗的认信解释，应与古代不同用法区别'],correct:1,why:'海44把信徒的安慰指向基督所承担的极深痛苦，不能据此抹去早期用语的复杂历史。'}];
quizzes.forEach((q,i)=>{const card=document.createElement('article');card.className='quiz-card';const h=document.createElement('h3');h.textContent=`${i+1}. ${q.q}`;card.append(h);const feedback=document.createElement('p');feedback.className='quiz-feedback';feedback.setAttribute('aria-live','polite');q.a.forEach((a,j)=>{const b=document.createElement('button');b.textContent=a;b.onclick=()=>{card.querySelectorAll('button').forEach(x=>x.classList.remove('correct','incorrect'));b.classList.add(j===q.correct?'correct':'incorrect');feedback.textContent=(j===q.correct?'✓ 正确。':'再想一想。')+q.why};card.append(b)});card.append(feedback);$('#quiz').append(card)});
